import { OrderPosition, OrderRepository } from './repository';
import { ListRequest, Order, Page } from './types';

// Cursor format: createdAt + '|' + id. Neither field contains '|'.
function parseCursor(cursor: string): OrderPosition {
  const parts = cursor.split('|');
  if (parts.length !== 2 || parts[0] === '' || parts[1] === '') {
    throw new Error('invalid request');
  }
  return { createdAt: parts[0], id: parts[1] };
}

function cursorOf(order: Order): string {
  return order.createdAt + '|' + order.id;
}

export class OrderHandler {
  constructor(private readonly repository: OrderRepository) {}
  list(request: ListRequest): Page {
    if (!request.tenant || !Number.isInteger(request.limit) || request.limit < 1 || request.limit > 100) {
      throw new Error('invalid request');
    }
    let after: OrderPosition | undefined;
    if (request.cursor !== undefined) {
      if (typeof request.cursor !== 'string') {
        throw new Error('invalid request');
      }
      after = parseCursor(request.cursor);
    }
    // Tenant filter and ordering come first; the page is cut from that result.
    const matching = after === undefined
      ? this.repository.list(request.tenant)
      : this.repository.listAfter(request.tenant, after);
    const items = matching.slice(0, request.limit);
    const nextCursor = matching.length > request.limit ? cursorOf(items[items.length - 1]) : null;
    return { items, nextCursor };
  }
}
