// ---- cursor pagination ----
{
  const { OrderHandler: Handler } = require('../.build/handler');
  const { OrderRepository: Repo } = require('../.build/repository');

  // Independent reference model: filter by tenant, sort, keep rows after the cursor pair, cut the page.
  const cmp = (p, q) => (p.createdAt < q.createdAt ? -1 : p.createdAt > q.createdAt ? 1
    : p.id < q.id ? -1 : p.id > q.id ? 1 : 0);
  const refPage = (rows, tenant, limit, after) => {
    let list = rows.filter(r => r.tenant === tenant).sort(cmp);
    if (after) list = list.filter(r => cmp(r, after) > 0);
    const items = list.slice(0, limit);
    const last = items[items.length - 1];
    return { ids: items.map(r => r.id), nextCursor: list.length > limit ? `${last.createdAt}|${last.id}` : null };
  };
  const invalid = { name: 'Error', message: 'invalid request' };

  // Pages through the whole listing and returns every id seen, in order.
  const pageAll = (pg, tenant, limit) => {
    const ids = [];
    let cursor;
    for (let guard = 0; guard < 10000; guard++) {
      const page = pg.list(cursor === undefined ? { tenant, limit } : { tenant, limit, cursor });
      assert.ok(page.items.length <= limit);
      ids.push(...page.items.map(r => r.id));
      if (page.nextCursor === null) return ids;
      assert.equal(page.items.length, limit, 'a non-final page must be full');
      cursor = page.nextCursor;
    }
    assert.fail('pagination did not terminate');
  };

  const rows = [
    { id: 'c', tenant: 'a', createdAt: '2026-01-01', total: 1 },
    { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 2 },
    { id: 'b', tenant: 'a', createdAt: '2026-01-01', total: 3 },
    { id: 'z', tenant: 'other', createdAt: '2026-01-01', total: 4 },
    { id: 'd', tenant: 'a', createdAt: '2026-01-03', total: 5 },
    { id: 'B', tenant: 'a', createdAt: '2026-01-02', total: 6 },
    { id: '10', tenant: 'a', createdAt: '2026-01-02', total: 7 },
    { id: '9', tenant: 'a', createdAt: '2026-01-02', total: 8 },
  ];
  const snapshot = JSON.stringify(rows);
  const refs = rows.slice();
  const repo = new Repo(rows);
  const pg = new Handler(repo);
  // Tenant a in order: a,b,c (01-01); 10,9,B (01-02, ids compared as strings); d (01-03).
  const allA = ['a', 'b', 'c', '10', '9', 'B', 'd'];

  // Every page size reproduces the full order with no repeats or skips.
  for (let limit = 1; limit <= 8; limit++) {
    assert.deepEqual(pageAll(pg, 'a', limit), allA, `limit ${limit}`);
  }

  // First page (no cursor): tenant filter and limit as before; nextCursor is createdAt|id of last item.
  const first = pg.list({ tenant: 'a', limit: 2 });
  assert.deepEqual(first.items.map(r => r.id), ['a', 'b']);
  assert.equal(first.nextCursor, '2026-01-01|b');
  assert.deepEqual(Object.keys(first).sort(), ['items', 'nextCursor']);
  assert.deepEqual(pg.list({ tenant: 'a', limit: 3 }).items.map(r => r.id), ['a', 'b', 'c']);
  assert.equal(pg.list({ tenant: 'a', limit: 3 }).nextCursor, '2026-01-01|c');
  assert.equal(pg.list({ tenant: 'a', limit: undefined === 1 ? 1 : 1, cursor: undefined }).items[0].id, 'a');

  // nextCursor is null when no further matching order exists.
  assert.equal(pg.list({ tenant: 'a', limit: 7 }).nextCursor, null);
  assert.equal(pg.list({ tenant: 'a', limit: 100 }).nextCursor, null);
  assert.equal(pg.list({ tenant: 'a', limit: 1, cursor: '2026-01-03|d' }).nextCursor, null);
  assert.deepEqual(pg.list({ tenant: 'a', limit: 1, cursor: '2026-01-03|d' }).items, []);
  assert.equal(pg.list({ tenant: 'nobody', limit: 5 }).nextCursor, null);

  // Multi-page walk with an exact cursor value at each boundary.
  const p1 = pg.list({ tenant: 'a', limit: 3 });
  const p2 = pg.list({ tenant: 'a', limit: 3, cursor: p1.nextCursor });
  const p3 = pg.list({ tenant: 'a', limit: 3, cursor: p2.nextCursor });
  assert.deepEqual([p1, p2, p3].map(p => p.items.map(r => r.id)), [['a', 'b', 'c'], ['10', '9', 'B'], ['d']]);
  assert.deepEqual([p1.nextCursor, p2.nextCursor, p3.nextCursor], ['2026-01-01|c', '2026-01-02|B', null]);

  // A cursor resumes strictly after its pair even when the row was deleted.
  const deleted = rows.find(r => r.id === 'b');
  const withoutB = new Repo(rows.filter(r => r !== deleted));
  assert.deepEqual(new Handler(withoutB).list({ tenant: 'a', limit: 2, cursor: '2026-01-01|b' }).items.map(r => r.id), ['c', '10']);
  // A pair that matches no row at all also works: '2026-01-01|bb' sits between b and c.
  assert.deepEqual(pg.list({ tenant: 'a', limit: 2, cursor: '2026-01-01|bb' }).items.map(r => r.id), ['c', '10']);

  // A cursor pair that belongs to another tenant: filter first, then paginate.
  // Tenant a rows after 2026-01-01|z (z belongs to 'other') are 10,9,B,d.
  const q1 = pg.list({ tenant: 'a', limit: 2, cursor: '2026-01-01|z' });
  assert.deepEqual(q1.items.map(r => r.id), ['10', '9']);
  assert.equal(q1.nextCursor, '2026-01-02|9');
  assert.deepEqual(pg.list({ tenant: 'a', limit: 2, cursor: q1.nextCursor }).items.map(r => r.id), ['B', 'd']);
  assert.equal(pg.list({ tenant: 'a', limit: 100, cursor: '2026-01-03|zz' }).nextCursor, null);

  // Invalid tenant, limit or cursor always throws 'invalid request'.
  const bad = [
    { tenant: '', limit: 1 },
    { tenant: 'a', limit: 0 },
    { tenant: 'a', limit: 101 },
    { tenant: 'a', limit: 1.5 },
    { tenant: 'a', limit: NaN },
    { tenant: 'a', limit: '1' },
    { tenant: 'a' },
    { tenant: 'a', limit: 1, cursor: '' },
    { tenant: 'a', limit: 1, cursor: 'nopipe' },
    { tenant: 'a', limit: 1, cursor: '|b' },
    { tenant: 'a', limit: 1, cursor: '2026-01-01|' },
    { tenant: 'a', limit: 1, cursor: '|' },
    { tenant: 'a', limit: 1, cursor: 'a|b|c' },
    { tenant: 'a', limit: 1, cursor: 5 },
    { tenant: 'a', limit: 1, cursor: null },
    { tenant: '', limit: 1, cursor: '2026-01-01|a' },
  ];
  for (const req of bad) assert.throws(() => pg.list(req), invalid, JSON.stringify(req));
  assert.equal(pg.list({ tenant: 'a', limit: 1 }).items.length, 1);
  assert.equal(pg.list({ tenant: 'a', limit: 1, cursor: undefined }).items[0].id, 'a');

  // Input array and rows are never mutated.
  pageAll(pg, 'a', 2);
  pg.list({ tenant: 'a', limit: 3, cursor: '2026-01-01|b' });
  repo.list('a');
  repo.listAfter('a', { createdAt: '2026-01-01', id: 'b' });
  assert.equal(JSON.stringify(rows), snapshot);
  assert.equal(rows.length, refs.length);
  rows.forEach((r, i) => assert.equal(r, refs[i]));

  // Randomized comparison against the reference model, with many equal dates.
  let seed = 42;
  const rnd = n => { seed = (Math.imul(seed, 1103515245) + 12345) >>> 0; return seed % n; };
  const dates = ['2025-12-31', '2026-01-01', '2026-01-02', '2026-01-03'];
  const idPool = ['a', 'aa', 'b', 'B', '10', '9', 'x', 'zz'];
  const tenants = ['a', 'b', 'c', 'd'];
  for (let trial = 0; trial < 300; trial++) {
    const seen = new Set();
    const data = [];
    const n = rnd(14);
    for (let i = 0; i < n; i++) {
      const r = { tenant: ['a', 'b', 'c'][rnd(3)], createdAt: dates[rnd(dates.length)], id: idPool[rnd(idPool.length)], total: i };
      const key = `${r.tenant}|${r.createdAt}|${r.id}`;
      if (seen.has(key)) continue; // ids are unique within a tenant
      seen.add(key);
      data.push(r);
    }
    const dataSnap = JSON.stringify(data);
    const h = new Handler(new Repo(data));
    for (const tenant of tenants) {
      for (const limit of [1, 2, 3, 5, 100]) {
        assert.deepEqual(pageAll(h, tenant, limit), refPage(data, tenant, 100, null).ids.length >= 0
          ? refPage(data, tenant, 1e9, null).ids : [], `trial ${trial} tenant ${tenant} limit ${limit}`);
        const after = { createdAt: dates[rnd(dates.length)], id: idPool[rnd(idPool.length)] };
        const got = h.list({ tenant, limit, cursor: `${after.createdAt}|${after.id}` });
        const want = refPage(data, tenant, limit, after);
        assert.deepEqual(got.items.map(r => r.id), want.ids, `trial ${trial} cursor ${after.createdAt}|${after.id}`);
        assert.equal(got.nextCursor, want.nextCursor, `trial ${trial} cursor next`);
      }
    }
    assert.equal(JSON.stringify(data), dataSnap);
  }
}

